// Elige el modelo de primera reclamación (dosier) del supuesto clasificado
const clas = $('Parsear JSON Respuesta de IA2').first().json;
const modelos = $input.all().map(i => i.json).filter(j => j && j.model_number && !j.error);
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const sub = norm(clas.subcategory);

let m = modelos.find(x => norm(x.subcategory_id) === sub)
  || modelos.find(x => norm(x.subcategory_name) === sub)
  || (sub ? modelos.find(x => norm(x.subcategory_name).includes(sub) || sub.includes(norm(x.subcategory_name))) : null);
if (!m && modelos.length === 1) m = modelos[0];

return [{
  json: {
    modeloEncontrado: Boolean(m),
    modelo: m ? {
      modelo: m.model_number,
      supuesto: m.subcategory_name,
      destinatario: m.recipient,
      asunto: m.subject,
      carta: m.body,
      pruebasRecomendadas: m.evidence,
      advertencia: m.warning,
      viaPosterior: m.escalation
    } : null
  }
}];

const ext = $('Parsear JSON Respuesta de IA2').first().json;
const parte = $input.all().map(i => i.json).find(j => j && j.id) || null;
const actual = (parte && parte.contact_details) || {};
const nuevo = { ...actual };
const email = String(ext.opposingPartyEmail || '').trim().toLowerCase();
if (!actual.email && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { nuevo.email = email; nuevo.email_source = 'documentos'; }
if (!actual.postal_address && ext.opposingPartyAddress) nuevo.postal_address = String(ext.opposingPartyAddress).slice(0, 300);
if (!actual.tax_id && ext.opposingPartyTaxId) nuevo.tax_id = String(ext.opposingPartyTaxId).slice(0, 20);
const cambia = Boolean(parte) && JSON.stringify(nuevo) !== JSON.stringify(actual);
return [{ json: { partyId: parte ? parte.id : null, cambia, contactDetails: nuevo } }];
